{selectedEmployee && (
  <UpdateForm>
    <h3>Update Employee Salary Details</h3>
    <Input
      type="text"
      value={selectedEmployee.phone}
      readOnly
      placeholder="Phone Number"
    />
    <Input
      type="date"
      placeholder="Start Date"
      value={salaryDetails.startDate}
      onChange={(e) => {
        setSalaryDetails({ ...salaryDetails, startDate: e.target.value });
        handleDateChange();
      }}
    />
    <Input
      type="date"
      placeholder="End Date"
      value={salaryDetails.endDate}
      onChange={(e) => {
        setSalaryDetails({ ...salaryDetails, endDate: e.target.value });
        handleDateChange();
      }}
    />
    <Input
      type="number"
      placeholder="Expense"
      value={salaryDetails.expense}
      onChange={(e) => setSalaryDetails({ ...salaryDetails, expense: e.target.value })}
    />
    <Button onClick={updateEmployee}>Update Salary</Button>
  </UpdateForm>
)}



